H=[['拉丁语 terminus','边界；界标；尽头']]
DET=H+[['拉丁 dē- + termināre → dētermināre','划清界限；限定、定下来'],['古法语 determiner → 中古英语 determinen → determine','确定；查明；决定']]
TERMINAL=H+[['后期拉丁 terminālis → 英语 terminal','边界、末端的 → 末端的；终端']]
TERM=H+[['拉丁语及中世纪拉丁的时间、约定、用语义 → 古法语 terme','划定的时段、条件或表达'],['中古英语 terme → 英语 term','期限、学期；条件；术语；项']]
def D(h,label,meaning):return h+[[label,meaning]]
W=[
E('determine','英 /dɪˈtɜːmɪn/；美 /dɪˈtɜːrmɪn/','确定；查明；决定','原本有许多可能，调查或条件把范围逐渐收窄，最终定出一个结果。','拉丁 dē- 加强 + termināre“划定界限”，经法语传入；这里 de- 不是简单的“去掉”。',DET,'调查可以 determine the cause“查明原因”；材料可以 determine the cost“决定成本”。前者把答案找出来，后者让结果成为这样。','determine whether；determine the cause；be determined by。','decide 常指人作选择；determine 也可说事实、条件把结果定下来。',('The test will determine whether the pipe is leaking.','测试将查明管道是否漏水。'),('The size of the room determines how much paint we need.','房间大小决定我们需要多少油漆。'),sources=['https://www.etymonline.com/word/determine']),
E('terminal','英 /ˈtɜːmɪnəl/；美 /ˈtɜːrmɪnəl/','终端；航站楼；末端的；晚期致命的','先抓“路线或连接到了这一端”。飞机旅程在航站楼接上地面交通；电脑终端则让人从这一端与系统交互。','来自后期拉丁 terminālis，接 terminus“边界、尽头”；各专门意思围绕末端、终点发展。',TERMINAL,'名词也可指电路端子。terminal illness 中是疾病已到无法治愈、会致命的阶段；词本身不指定还剩多久。','an airport terminal；a computer terminal；a terminal illness。','terminal 是端点或终点相关；temporary 是暂时的，来源是“时间”，别因开头相似看错。',('Our flight leaves from Terminal 2.','我们的航班从二号航站楼出发。'),('Type the command into the terminal window.','把这条命令输入终端窗口。'),sources=['https://en.wiktionary.org/wiki/terminal#English','https://www.merriam-webster.com/dictionary/terminal']),
E('determination','英 /dɪˌtɜːmɪˈneɪʃən/；美 /dɪˌtɜːrmɪˈneɪʃən/','决心；确定；测定','一方面是把答案定下来，另一方面是把方向定下来之后坚持走。前者是测定，后者是决心。','拉丁 dēterminātiō 经法语进入英语；现代可联系 determine + -ation，历史名词已有自己的借入路线。',[H[0],['拉丁 dētermināre → dēterminātiō；古法语 determinacion','限定、确定 → 确定的行为'],['中古英语 → determination','确定；测定；坚定的意志']],'show determination 是表现出决心；determination of a value 是测定数值。别在实验报告里一看它就译成“决心”。','with determination；determination to do；the determination of。','decision 是作出的决定；determination 常是推动自己把决定坚持到底的劲头。',('She approached the task with quiet determination.','她以沉静而坚定的决心着手完成任务。'),('The experiment allows accurate determination of the sample’s mass.','这个实验能准确测定样本质量。'),sources=['https://www.etymonline.com/word/determination']),
E('termination','英 /ˌtɜːmɪˈneɪʃən/；美 /ˌtɜːrmɪˈneɪʃən/','终止；结束；末端','给原本还在延续的事情划一道终线：到这里停止。','借自拉丁 terminātiō，来自 termināre“划界、结束”；现代对应 terminate，但名词不必经过英语动词再造。',[H[0],['拉丁 termināre → terminātiō','设置终点 → 终止的行为'],['英语 termination','终止；结束；末端']],'常见于合同、雇佣、程序运行等正式语境。它说明结束，是否提前、是否有争议由上下文决定。','early termination；termination of a contract；termination date。','completion 通常表示事情做完；termination 只说被终止，可能尚未完成。',('The agreement specifies a termination date.','协议规定了终止日期。'),('Unexpected termination of the program caused the data to be lost.','程序意外终止，导致数据丢失。'),sources=['https://www.etymonline.com/word/termination']),
E('terminally','英 /ˈtɜːmɪnəli/；美 /ˈtɜːrmɪnəli/','处于致命疾病晚期地；在末端；无可挽回地〔比喻〕','terminally ill 里的终点指生命终点；在夸张说法里，也能把“已经没救”放到一件糟糕事情上。','terminal + -ly，副词沿用 terminal 的不同末端义。',D(TERMINAL,'英语 terminal → terminally','末端的 → 处于末端、以末端方式'),'最常见 terminally ill。文学或评论中的 terminally boring 是夸张说无聊透顶，不能照字面理解成致命。','terminally ill；terminally bored〔夸张〕。','seriously ill 是病得严重；terminally ill 说的是疾病的致命、无法治愈阶段，程度和预后重点不同。',('The charity supports terminally ill patients and their families.','这家慈善机构支持患有晚期致命疾病的人及其家属。'),('He looked terminally bored during the long presentation.','那场漫长演示中，他看起来无聊透顶。'),sources=['https://www.merriam-webster.com/dictionary/terminally','https://en.wiktionary.org/wiki/terminally#English']),
E('determinant','英 /dɪˈtɜːmɪnənt/；美 /dɪˈtɜːrmɪnənt/','决定因素；行列式〔数学〕','在众多条件里，有一个因素会把结果推向某个方向；数学里，这个名字还给了方阵的一个重要数值。','借法语 déterminant，属于 déterminer“确定”的词族；现代可联系 determine 与 -ant。',[H[0],['拉丁 dētermināre → 法语 déterminer / déterminant','确定 → 起决定作用的'],['英语 determinant','决定因素；行列式']],'普通用法问“什么决定结果”；数学中二阶行列式是 ad−bc，可帮助判断方阵能否求逆。两个意思都抓住判定作用。','a key determinant of；calculate the determinant。','determiner 常是语法里的限定词；determinant 在日常分析中是因素，在数学中是行列式。',('Access to transport is a major determinant of where people can work.','交通条件是决定人们能去哪里工作的主要因素。'),('A square matrix with a nonzero determinant is invertible.','行列式非零的方阵可逆。'),sources=['https://en.wiktionary.org/wiki/determinant#English','https://math.mit.edu/~mckernan/Teaching/12-13/Autumn/18.02/l_3.pdf']),
E('determinism','英 /dɪˈtɜːmɪnɪzəm/；美 /dɪˈtɜːrmɪnɪzəm/','决定论；确定性','把世界或程序想成一套规则：完整起点和条件一旦相同，后面的走向就被这些条件固定。','经法语 déterminisme 借入，联系 determine 与 -ism“学说、原则”。',[H[0],['拉丁 dētermināre → 法语 déterminer / déterminisme','确定 → 事件被条件决定的学说'],['英语 determinism','决定论；行为由给定状态、输入决定的性质']],'哲学里讨论过去状态与规律是否决定未来；计算中常说给定同样状态和输入会得同样结果。是否容得下自由意志，是另一个需要论证的问题。','causal determinism；strict determinism；determinism in computation。','fatalism 常是无论做什么某结果都注定；determinism 中人的行动也在因果过程里，不能直接推出“努力没用”。',('The course compares determinism with different accounts of free will.','课程比较决定论与不同的自由意志理论。'),('The test checks the program’s determinism under identical conditions.','测试检查程序在相同条件下是否具有确定性。'),sources=['https://plato.stanford.edu/archives/spr2022/entries/determinism-causal/index.html','https://en.wiktionary.org/wiki/determinism#English']),
E('interminable','英 /ɪnˈtɜːmɪnəbəl/；美 /ɪnˈtɜːrmɪnəbəl/','没完没了的；漫长得令人厌烦的','会议开了很久，仍看不到结束的边，你忍不住想“到底什么时候完”。','经法语借自后期拉丁 interminābilis；in-“不” + terminābilis“可结束的”。不是 inter-“之间”+ minable。',[H[0],['后期拉丁 in- + terminābilis → interminābilis','不 + 可结束的 → 无尽的'],['法语 interminable → 英语 interminable','没完没了的']],'通常是带不耐烦的夸张，并非数学上真的无限；常用来形容等待、会议、争论。','an interminable wait；interminable meetings。','long 只说长；interminable 还传达“长得烦、看不到头”。',('After an interminable wait, the bus finally arrived.','等了仿佛没完没了的一段时间后，巴士终于来了。'),('We sat through another interminable discussion about the logo.','我们又熬过了一场没完没了的标志设计讨论。'),sources=['https://www.etymonline.com/word/interminable']),
E('determinative','英 /dɪˈtɜːmɪnətɪv/；美 /dɪˈtɜːrməneɪtɪv/，也 /-nətɪv/','起决定作用的；限定成分；表义分类符号','一条信息把答案范围圈小，或一个符号把某个词归到具体意义类别；都在做“限定”。','经法语 déterminatif，属于拉丁 dētermināre 词族；现代可联系 determine 与 -ative。',[H[0],['拉丁 dētermināre → 法语 déterminer / déterminatif','确定、限定 → 起限定作用的'],['英语 determinative','决定性的；限定成分或表义符号']],'形容词常说决定性因素；名词在语法书中可指限定词类，在古文字研究中可指帮助区分词义类别的符号。具体术语范围随分析体系不同。','be determinative of；a determinative sign。','determinative 强调限定或决定作用；descriptive 主要作描述。语法中的 determinative 与 determiner 有时还区分词类与功能。',('Cost was important but not determinative of the final choice.','成本很重要，但没有决定最终选择。'),('The determinative helps the reader identify the word’s semantic category.','这个表义分类符号帮助读者辨认词的意义类别。'),sources=['https://www.merriam-webster.com/dictionary/determinative','https://en.wiktionary.org/wiki/determinative#English']),
E('determiner','英 /dɪˈtɜːmɪnə/；美 /dɪˈtɜːrmɪnər/','限定词；起决定作用的人或因素','只说 book，范围很宽；加上 this，便把目光指向“这本”。语法里的 determiner 就在帮名词圈定所指。','determine + -er，英语派生；语法用法抓的是限定指称的作用，不是“下决心的人”。',D(DET,'英语 determine + -er → determiner','确定、限定 → 起限定作用的成分'),'入门语法常把 the、a、this、my 等列为限定词。不同语法框架对词类与句法功能的命名有差别。','a possessive determiner；a demonstrative determiner。','adjective 常描述“怎样的”，如 red；determiner 常帮助指出“哪个、谁的、多少”，如 this、my。',('In “this book”, “this” is a determiner.','在 this book 中，this 是限定词。'),('The teacher asked us to underline the determiners in each sentence.','老师让我们给每句中的限定词画下划线。'),sources=['https://en.wiktionary.org/wiki/determiner#English']),
E('term','英 /tɜːm/；美 /tɜːrm/','期限；学期；任期；条件；术语；项','给时间划出一段，是 term；给概念划一个名称，也是 term。合同里的 terms，则把双方能做什么、要做什么划清。','经法语 terme 来自拉丁 terminus“边界、尽头”；现代名词、动词都以这个完整词为基。',TERM,'a school term 是一个学期；technical terms 是术语；terms and conditions 是条款。数学的 a term 是表达式中的一项。','in the long term；on these terms；a technical term。','semester 常指一学年中的两个学期之一；term 更宽，具体划分随学校。term 也远不止学校用法。',('We will study poetry next term.','下学期我们会学习诗歌。'),('The two sides agreed on the terms of the sale.','双方就买卖条件达成一致。'),('Please explain that technical term in plain language.','请用通俗的话解释那个专业术语。'),sources=['https://www.etymonline.com/word/term']),
E('terminate','动词：英 /ˈtɜːmɪneɪt/；美 /ˈtɜːrmɪneɪt/','终止；结束；到达终点','把一条仍在继续的线截在这里：服务到此结束，列车也可以到站终止运行。','来自拉丁 terminātus，与 termināre“设限、结束”相接；经中古英语的动词形式传下。',[H[0],['拉丁 termināre → terminātus；中古英语 terminaten','设置终点、使结束 → 英语动词'],['英语 terminate','终止；结束于']],'比 end 正式。既能及物说 terminate a process，也能不及物说某路线 terminates at 某处。','terminate a contract；terminate a process；terminate at。','pause 是暂时停下，之后可能接着做；terminate 把当前过程结束掉。',('The railway line terminates at the harbour.','这条铁路的终点在港口。'),('The system terminated the process after an error occurred.','错误发生后，系统终止了那个进程。'),sources=['https://www.etymonline.com/word/terminate']),
E('terminus','英 /ˈtɜːmɪnəs/；美 /ˈtɜːrmɪnəs/','终点；终点站','沿着线路一直走，已经没有下一站了，那里就是 terminus。','直接借拉丁 terminus“边界、尽头”；与经法语变短的 term 是同源双式词。',[H[0],['英语直接借入 terminus','终点；路线尽头']],'常用于交通线路或地理描述。复数可用 termini 或 terminuses；不必误认为所有大车站都是终点站。','the northern terminus；a bus terminus。','terminal 可以指一座航站楼或设备端口；terminus 更直接地说线路的尽头。',('We got off at the bus terminus.','我们在公交终点站下了车。'),('The town marks the southern terminus of the trail.','这座小镇是这条步道的南端终点。'),sources=['https://www.etymonline.com/word/terminus']),
E('determined','英 /dɪˈtɜːmɪnd/；美 /dɪˈtɜːrmɪnd/','下定决心的；坚定的；已确定的','你把方向选定，遇到阻力也不轻易退；这就是形容人的 determined。','determine + -ed；也承接确定、限定的历史意义。形容词强调坚定，分词可强调某事已被确定。',D(DET,'英语 determine → determined','把方向或结果定下 → 坚定的；已确定的'),'be determined to do 是下决心做；be determined by 是由某因素决定。后面的介词能帮你迅速分清意思。','determined to succeed；a determined effort；determined by。','stubborn 可能是不肯听合理意见；determined 更常肯定为目标坚持不懈。',('She was determined to finish the course.','她下定决心要完成课程。'),('The price is determined by the size of the order.','价格由订单规模决定。'),sources=['https://en.wiktionary.org/wiki/determined#English','https://www.etymonline.com/word/determined']),
E('indeterminate','英 /ˌɪndɪˈtɜːmɪnət/；美 /ˌɪndɪˈtɜːrmɪnət/','无法确定的；界限不明确的','轮廓还没圈定，或者已有信息不足以选出唯一答案，这时就可以说 indeterminate。','in-“不” + determinate“确定的”；远接拉丁 dēterminātus。这不是单纯给 determine 后面加 -ate。',[H[0],['拉丁 dēterminātus；否定形式 indēterminātus','划定、确定的；不确定的'],['英语 indeterminate','未定；不能唯一确定的']],'常见 a person of indeterminate age“看不出年龄的人”。数学里的 indeterminate form 说某些形式本身不足以确定极限，不等于所有结果都不存在。','an indeterminate period；of indeterminate age；an indeterminate form。','unknown 只是我们不知道；indeterminate 常强调尚未定下，或现有条件无法给出唯一答案。',('The work was delayed for an indeterminate period.','这项工作被推迟，延误多久尚不确定。'),('The photograph shows a man of indeterminate age.','照片上是个看不出具体年龄的男人。'),sources=['https://en.wiktionary.org/wiki/indeterminate#English','https://www.etymonline.com/word/indeterminate']),
]
ROOT=dict(id='C1495',meaning='边界、尽头；把范围或结果定下来',core='TERMIN = BOUNDARY / END',image='在地上插一根界桩：“到这里为止。”放到路线，是 terminus；放到过程，是 terminate；把尚不明确的范围圈定，就是 determine。方向一旦定下来，人也可以变得 determined。',intro='词根来自拉丁 terminus“边界、界标、尽头”。本质不是一律“停止”，而是某个范围有了明确的边。它既能表示结束，也能表示限定时间、概念或答案。',forms='term 经法语缩短，terminus 是直接借入的拉丁形式。determine 含 dē- + termināre，不要把 de- 一律当“去除”。interminable 的开头是 in- + termin-，并非 inter-。determinant、determiner、determinative 各有专门用法，不能只凭中文“决定”相互替换。',branches=[['范围与名称','term, terminus, terminal'],['让过程结束','terminate, termination'],['查明答案或坚持方向','determine, determination, determined'],['限定与可确定性','determiner, determinant, indeterminate']],contrasts='determine 可查明事实，也可说条件决定结果；decide 更常说人作选择。termination 不保证任务完成。terminal 与 temporary 不是同一词根。interminable 是看不到尽头，不是“两个末端之间”。',practice='We determined the cause of the delay and set a new termination date. The team remained determined to finish within the term.\n\n我们查明了延误原因，并设定了新的终止日期。团队仍下定决心在期限内完成。',words=[w['word'] for w in W])
